import me.atam.atam4jsampleapp.testsupport.AcceptanceTest;
import me.atam.atam4jsampleapp.testsupport.Atam4jApplicationStarter;
import org.junit.Test;

import javax.ws.rs.core.Response;

import static me.atam.atam4jsampleapp.testsupport.AcceptanceTestTimeouts.TEN_SECONDS_IN_MILLIS;
import static org.hamcrest.CoreMatchers.hasItem;
import static org.hamcrest.CoreMatchers.is;
import static org.junit.Assert.assertThat;

public class PassingTestAcceptanceTest extends AcceptanceTest {

    @Test
    public void givenPassingTest_whenTestsEndpointCalledBeforeTestRun_thenTooEarlyMessageReceived(){
        //given
        dropwizardTestSupportAppConfig = Atam4jApplicationStarter
                                            .startApplicationWith(TEN_SECONDS_IN_MILLIS, PassingTestWithNoCategory.class);
        //when
        Response testRunResultFromServer = getTestRunResultFromServer(getTestsURI());
        //then
        assertThat(testRunResultFromServer.getStatus(), is(Response.Status.OK.getStatusCode()));
        assertThat(
                testRunResultFromServer.readEntity(TestsRunResult.class).getStatus(),
                is(TestsRunResult.Status.TOO_EARLY)
        );
    }

    @Test
    public void givenSampleApplicationStartedWithPassingTest_whenCriticalHealthCheckCalledBeforeTestRun_thenTooEarlyMessageReceived(){

        dropwizardTestSupportAppConfig = Atam4jApplicationStarter
                .startApplicationWith(TEN_SECONDS_IN_MILLIS, PassingTest.class);

        Response testRunResultFromServer = getCriticalTestRunResultFromServer();
        assertThat(testRunResultFromServer.getStatus(), is(Response.Status.OK.getStatusCode()));
        assertThat(
                testRunResultFromServer.readEntity(TestsRunResult.class).getStatus(),
                is(TestsRunResult.Status.TOO_EARLY)
        );
    }

    @Test
    public void givenPassingTest_whenTestsEndpointCalledAfterTestRun_thenOKMessageReceived(){
        //given
        dropwizardTestSupportAppConfig = Atam4jApplicationStarter.startApplicationWith(0, PassingTestWithNoCategory.class);
        //when
        Response response = getResponseFromTestsEndpointOnceTestsRunHasCompleted();
        TestsRunResult testRunResult = response.readEntity(TestsRunResult.class);
        //then
        assertThat(response.getStatus(), is(Response.Status.OK.getStatusCode()));
        assertThat(testRunResult.getTests().size(), is(1));
        assertThat(
                testRunResult.getTests(),
                hasItem(new IndividualTestResult(PassingTestWithNoCategory.class.getName(), "testThatPasses", true))
        );
    }




}

package me.atam.atam4jsampleapp.testsupport;

import io.dropwizard.testing.DropwizardTestSupport;
import me.atam.atam4j.PollingPredicate;
import me.atam.atam4jdomain.TestsRunResult;
import me.atam.atam4jsampleapp.ApplicationConfiguration;
import org.glassfish.jersey.client.JerseyClientBuilder;
import org.junit.After;

import javax.ws.rs.client.Client;
import javax.ws.rs.core.Response;

import static me.atam.atam4jsampleapp.testsupport.AcceptanceTestTimeouts.MAX_ATTEMPTS;
import static me.atam.atam4jsampleapp.testsupport.AcceptanceTestTimeouts.RETRY_POLL_INTERVAL;
import static org.junit.Assert.assertTrue;

public abstract class AcceptanceTest {

    private static final Client client = new JerseyClientBuilder().build();
    protected DropwizardTestSupport<ApplicationConfiguration> dropwizardTestSupportAppConfig;

    @After
    public void stopApplication() {
        dropwizardTestSupportAppConfig.after();
    }

    public Response getTestRunResultFromServer(String testsURI) {
        return client.target(
                testsURI)
                     .request()
                     .get();
    }

    public Response getCriticalTestRunResultFromServer() {
        return client.target(String.format("http://localhost:%d/tests/priority-1", dropwizardTestSupportAppConfig.getLocalPort()))
                .request()
                .get();
    }

    public String getTestsURI() {
        return String.format("http://localhost:%d/tests", dropwizardTestSupportAppConfig.getLocalPort());
    }

    public Response getResponseFromTestsWithCategoryOnceTestRunHasCompleted(String category) {
        waitUntilTestRunHasCompleted();
        return getTestRunResultFromServer(getTestsURI() + "/" + category);
    }

    public Response getResponseFromTestsEndpointOnceTestsRunHasCompleted() {
        waitUntilTestRunHasCompleted();
        return getTestRunResultFromServer(getTestsURI());
    }

    private void waitUntilTestRunHasCompleted() {
        PollingPredicate<Response> responsePollingPredicate = new PollingPredicate<>(
                MAX_ATTEMPTS,
                RETRY_POLL_INTERVAL,
                response -> !response.readEntity(TestsRunResult.class).getStatus().equals(TestsRunResult.Status.TOO_EARLY),
                () ->  getTestRunResultFromServer(getTestsURI()));

        assertTrue(responsePollingPredicate.pollUntilPassedOrMaxAttemptsExceeded());
    }
}

